property.value:
let $outputName := function($n) {
      matches(string($n), '^(stderr|stdout|stackTrace|errorOutput)$|(Stderr|Stdout|StackTrace|ErrorOutput)$')
    },
    $outputText := function($e) {
      let $base := $e/descendant-or-self::*[not(self::MethodCall[@MethodName = ('toString', 'trim', 'strip')][not(*[1][pmd-java:typeIs('java.io.StringWriter')])])][1]
      return exists($base/self::VariableAccess[$outputName(@Name)])
          or exists($base/self::FieldAccess[$outputName(@Name)])
          or exists($base/self::MethodCall[@MethodName = 'toString'][*[1][pmd-java:typeIs('java.io.StringWriter')]])
    },
    $sink := function($n) {
      $n/ancestor::*[self::ConstructorCall[pmd-java:typeIs('java.lang.Throwable')]
                     or self::MethodCall[@MethodName = ('error', 'fatal')][*[1][self::VariableAccess or self::FieldAccess]]
                     or self::ExpressionStatement or self::LocalVariableDeclaration or self::ReturnStatement
                     or self::LambdaExpression or self::IfStatement or self::ThrowStatement][1]
                    [self::ConstructorCall or self::MethodCall]
    },
    $keepsEnd := function($s) {
      exists($s//MethodCall[@MethodName = 'substring'][ArgumentList/@Size = 1])
    }
return
(//MethodCall[@MethodName = 'substring'][ArgumentList/@Size = 2][ArgumentList/*[1][self::NumericLiteral][@ValueAsInt = 0]]
   [not(ArgumentList/*[2][self::NumericLiteral[@ValueAsInt < 40]
                          or self::InfixExpression[@Operator = '-']
                          or self::MethodCall[@MethodName = ('indexOf', 'lastIndexOf')]])]
   [$outputText(*[1])]
 | //MethodCall[@MethodName = ('left', 'abbreviate', 'truncate')][ArgumentList/@Size = 2][*[1][self::TypeExpression]]
   [$outputText(ArgumentList/*[1])][not(ArgumentList/*[2][self::NumericLiteral][@ValueAsInt < 40])])
  [let $direct := $sink(.),
       $held := ancestor::VariableDeclarator[1][parent::LocalVariableDeclaration][VariableId/@Name],
       $method := ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration or self::LambdaExpression or self::Initializer][1],
       $heldSinks := for $use in $method//VariableAccess[@Name = $held/VariableId/@Name] return $sink($use)
   return not($keepsEnd($method))
     and (exists($direct) or (exists($held) and $held/*[2] is . and exists($heldSinks)))]
